// Citad3L Worker entry: wraps the OpenNext worker and serves /media/* with HTTP Range support.
// Workers Static Assets answers Range requests with a full 200, and Safari/iOS will not play
// <video> without 206 partial responses. So /media/* runs worker-first (see wrangler.jsonc).
// @ts-ignore: generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";
import { capRequestBody, csrfBlockReason, httpsRedirect, withSecurityHeaders } from "./security/edge.mjs";
import { ComputerHub, computerSocket } from "./worker/computer-hub.js";

function withNoIndex(res) {
  if (res.headers.get("X-Robots-Tag")) return res;
  const headers = new Headers(res.headers);
  headers.set("X-Robots-Tag", "noindex, nofollow");
  return new Response(res.body, { status: res.status, statusText: res.statusText, headers });
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    // Plain HTTP (in-app browsers opening http:// links) goes to https before anything else.
    const toHttps = httpsRedirect(request);
    if (toHttps) return toHttps;
    // www is its own Custom Domain; send it to the apex so cookies and APP_URL stay on citad3l.io.
    if (url.hostname === "www.citad3l.io") {
      url.hostname = "citad3l.io";
      url.protocol = "https:";
      return withSecurityHeaders(Response.redirect(url.toString(), 301), env, new URL(request.url));
    }
    // CSRF: refuse state-changing /api/* calls from foreign origins (see security/edge.mjs).
    const blocked = csrfBlockReason(request, env);
    if (blocked) {
      const res = new Response(JSON.stringify({ error: { code: "forbidden_origin", message: "Request blocked." } }), {
        status: 403,
        headers: { "content-type": "application/json", "X-Robots-Tag": "noindex, nofollow" },
      });
      return withSecurityHeaders(res, env, url);
    }
    if (url.pathname === "/api/computer/ws") return computerSocket(request, env);
    if (url.pathname.startsWith("/media/") && (request.method === "GET" || request.method === "HEAD")) {
      return withSecurityHeaders(await serveMedia(request, env), env, url);
    }
    if (isHashedStatic(url.pathname) && (request.method === "GET" || request.method === "HEAD")) {
      return withSecurityHeaders(await serveCachedAsset(request, env, CACHE_YEAR), env, url);
    }
    if (isPublicIcon(url.pathname) && (request.method === "GET" || request.method === "HEAD")) {
      return withSecurityHeaders(await serveCachedAsset(request, env, CACHE_WEEK), env, url);
    }
    // Byte cap on unsafe /api/* bodies before Next/Auth.js read them.
    const capped = capRequestBody(request);
    if (capped.response) return withSecurityHeaders(capped.response, env, url);
    return withSecurityHeaders(withNoIndex(await handler.fetch(capped.request, env, ctx)), env, url);
  },
};

// Media files are cache-busted with ?v= on <source>/<img> URLs (see LoopVideo MEDIA_V).
const CACHE_YEAR = "public, max-age=31536000, immutable";
const CACHE_WEEK = "public, max-age=604800, stale-while-revalidate=2592000";

const MEDIA_HEADERS = {
  "Accept-Ranges": "bytes",
  "Cache-Control": CACHE_YEAR,
  "X-Robots-Tag": "noindex, nofollow",
  "X-Content-Type-Options": "nosniff",
};

function isHashedStatic(pathname) {
  return pathname.startsWith("/_next/static/");
}

function isPublicIcon(pathname) {
  return (
    pathname === "/favicon.ico" ||
    pathname === "/favicon.svg" ||
    pathname === "/favicon-32.png" ||
    pathname === "/apple-touch-icon.png" ||
    pathname === "/icon-192.png" ||
    pathname === "/icon-512.png" ||
    pathname === "/maskable-512.png" ||
    pathname === "/app-icon-512.png" ||
    pathname === "/mock-image.svg" ||
    pathname === "/manifest.webmanifest"
  );
}

async function serveCachedAsset(request, env, cacheControl) {
  const asset = await env.ASSETS.fetch(request);
  if (!asset.ok) return asset;
  const headers = new Headers(asset.headers);
  headers.set("Cache-Control", cacheControl);
  headers.set("X-Content-Type-Options", "nosniff");
  if (request.method === "HEAD") return new Response(null, { status: asset.status, headers });
  return new Response(asset.body, { status: asset.status, statusText: asset.statusText, headers });
}

async function serveMedia(request, env) {
  const range = request.headers.get("Range");
  const asset = await env.ASSETS.fetch(new Request(new URL(request.url).toString(), { method: "GET", headers: range ? { Range: range } : {} }));
  if (!asset.ok) return asset;
  const headers = new Headers(asset.headers);
  for (const [k, v] of Object.entries(MEDIA_HEADERS)) headers.set(k, v);
  // If the assets layer honoured the Range itself, pass its 206 straight through (no buffering).
  if (asset.status === 206) return new Response(request.method === "HEAD" ? null : asset.body, { status: 206, headers });

  const m = range && /^bytes=(\d*)-(\d*)$/.exec(range.trim());
  if (!m) {
    if (request.method === "HEAD") return new Response(null, { status: 200, headers });
    return new Response(asset.body, { status: 200, headers });
  }
  const buf = await asset.arrayBuffer();
  const size = buf.byteLength;
  let start, end;
  if (m[1] === "") { // suffix range: last N bytes
    const n = Number(m[2]);
    start = Math.max(0, size - n); end = size - 1;
  } else {
    start = Number(m[1]);
    end = m[2] === "" ? size - 1 : Math.min(Number(m[2]), size - 1);
  }
  if (!(start <= end) || start >= size) {
    headers.set("Content-Range", `bytes */${size}`);
    headers.delete("Content-Length");
    return new Response(null, { status: 416, headers });
  }
  headers.set("Content-Range", `bytes ${start}-${end}/${size}`);
  headers.set("Content-Length", String(end - start + 1));
  return new Response(request.method === "HEAD" ? null : buf.slice(start, end + 1), { status: 206, headers });
}

export { ComputerHub };

// Durable Object classes re-exported for parity with the generated worker (unused by this app).
// @ts-ignore
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
